/**
 * Unit tests for ByteQuadsCanonicalizer.toString()
 */
public class ByteQuadsCanonicalizer_toString_TriageGen1Test {

    @Test
    public void testToStringEmpty() {
        // Test toString for a newly created empty canonicalizer
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();

        String result = canonicalizer.toString();

        // Expected format: [className: size=0, hashSize=X, 0/0/0/0 pri/sec/ter/spill (=0), total:0]
        // Note: _count and _hashSize depend on internal implementation, but we verify the structure and counts.
        String className = ByteQuadsCanonicalizer.class.getName();

        assertTrue("Result should contain class name", result.contains(className));
        assertTrue("Result should show zero counts", result.contains("0/0/0/0 pri/sec/ter/spill (=0)"));
        assertTrue("Result should show total 0", result.contains("total:0"));
    }




}

package com.fasterxml.jackson.core.sym;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.util.InternCache;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ByteQuadsCanonicalizer.toString()
 */
public class ByteQuadsCanonicalizer_toString_TriageGen1Test {



    @Test
    public void testToStringWithData() {
        // Test toString after adding elements to ensure counts are reflected correctly
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();

        // Adding names to trigger different internal buckets/counts
        // We use different patterns to potentially hit different levels (primary, secondary, etc.)
        canonicalizer.addName("test1", 0x61);
        canonicalizer.addName("test2", 0x62);
        canonicalizer.addName("test3", 0x63);

        String result = canonicalizer.toString();
        String className = ByteQuadsCanonicalizer.class.getName();

        // Validate structure and presence of data
        assertTrue("Result should contain class name", result.contains(className));

        // The exact distribution (pri/sec/ter/spill) depends on the hash collisions.
        // However, the sum (pri+sec+ter+spill) must equal totalCount().
        // We use a regex to validate the pattern: [class: size=X, hashSize=Y, P/S/T/Sp pri/sec/ter/spill (=Sum), total:Z]
        String regex = "\\[" + className + ": size=\\d+, hashSize=\\d+, \\d+/\\d+/\\d+/\\d+ pri/sec/ter/spill \\(=(\\d+)\\), total:\\d+\\]";
        assertTrue("String format does not match expected pattern", result.matches(regex));

        // Verify internal consistency: totalCount() should match the sum in the string
        int total = canonicalizer.totalCount();
        assertTrue("Total count should be reflected in the string", result.contains("total:" + total));
    }


}

package com.fasterxml.jackson.core.sym;

import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.util.InternCache;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ByteQuadsCanonicalizer.toString()
 */
public class ByteQuadsCanonicalizer_toString_TriageGen1Test {





    @Test
    public void testToStringWithCollisions() {
        // To maximize coverage of the different count variables (pri, sec, tert, spill),
        // we attempt to force collisions. Since we can't easily control the hash,
        // we add many entries to ensure the internal state moves beyond just 'primary'.
        ByteQuadsCanonicalizer canonicalizer = ByteQuadsCanonicalizer.createRoot();

        for (int i = 0; i < 100; i++) {
            canonicalizer.addName("name" + i, i);
        }

        String result = canonicalizer.toString();
        int total = canonicalizer.totalCount();

        // Extract the sum part: (=X)
        int sumStart = result.indexOf("(=") + 2;
        int sumEnd = result.indexOf(")", sumStart);
        int sumInString = Integer.parseInt(result.substring(sumStart, sumEnd));

        assertEquals("The sum of pri/sec/ter/spill in toString must equal totalCount()", total, sumInString);
    }
}
